/*
 * Freestanding build configuration for TinyCC inside the OS101 kernel.
 *
 * Written by hand rather than generated by `./configure`: that script probes a
 * hosted OS, and we are compiling the compiler itself for
 * `x86_64-unknown-none-elf` against the libc shim. Keep this file next to the
 * sources and list every intentional deviation from a normal Unix build here.
 *
 *   CONFIG_TCC_STATIC   — no dlopen; TCC_IS_NATIVE still provides tcc_run stubs
 *   CONFIG_TCC_SEMLOCK 0 — no threads, no semaphores
 *   CONFIG_TCC_PIE      — executables are ET_DYN so the kernel can load them at
 *                         USER_BASE (which does not fit in 32-bit absolute
 *                         relocations of the small code model)
 *   CONFIG_TCC_BCHECK 0 / BACKTRACE 0 — avoid signal/ucontext dependencies
 *   CONFIG_TCC_PREDEFS 0 — we ship include/tccdefs.h and point -B at it
 */
#ifndef OS101_TCC_CONFIG_H
#define OS101_TCC_CONFIG_H

#define TCC_VERSION "0.9.28rc"

#define TCC_TARGET_X86_64 1
#define CONFIG_TCC_STATIC 1
#define CONFIG_TCC_SEMLOCK 0
#define CONFIG_TCC_BCHECK 0
#define CONFIG_TCC_BACKTRACE 0
#define CONFIG_TCC_PIE 1
#define CONFIG_TCC_MUSL 1
#define CONFIG_DWARF_VERSION 0

/* Paths used when -B is not set. The Rust driver always sets -B. */
#ifndef CONFIG_TCCDIR
#define CONFIG_TCCDIR "/disk/lib/tcc"
#endif

#define CONFIG_TCC_SYSINCLUDEPATHS "{B}/include:/disk/include"
#define CONFIG_TCC_LIBPATHS "{B}:/disk/lib"
#define CONFIG_TCC_CRTPREFIX "/disk/lib"
#define CONFIG_TCC_ELFINTERP "/lib/ld-os101.so.1"

/* No predef generation at build time — use the vendored tccdefs.h. */
#define CONFIG_TCC_PREDEFS 0

#endif
